const D = { scale:1, energy:.55, hue:32, speed:1, density:.5, x:.5, y:.86, pose:'lean', style:'noir', act:'stakeout', throw:.6, seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n;
const frc=v=>v-Math.floor(v);
const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453; return s-Math.floor(s);};
const sn=(tt,off)=>{const f=Math.floor(tt),xq=tt-f; return (fr(f+off)*(1-xq)+fr(f+1+off)*xq-.5)*2;};
if (S.lastBeat==null || K.beat<S.lastBeat) S.lastBeat=K.beat;
S.lastBeat=K.beat;

const u=Math.min(width,height);
const sc=u*P.scale/460;            // figure ~215 local tall -> ~0.47u
const bt=K.beat*P.speed;
const en=P.energy*(.5+.6*K.intensity);
const H=md(P.hue,360);
const chiaro=P.style==='noir', neon=P.style==='neon', xray=P.style==='xray', chalk=P.style==='chalk';

// ---- seed caches ----
if (S.seedUsed!==P.seed){
  S.seedUsed=P.seed;
  S.grain=[];
  for(let i=0;i<70;i++) S.grain.push({x:(fr(i*3+1)-.5), y:(fr(i*3+2)-.5), r:.4+fr(i*5+3)*1.3});
  S.smoke=[];
  for(let i=0;i<7;i++) S.smoke.push({ph:fr(i*7+4)*6.2832, sp:.5+fr(i*9+5)*.7, drift:(fr(i*11+6)-.5), w:6+fr(i*13+7)*5});
  S.rain=[];
  for(let i=0;i<80;i++) S.rain.push({x:fr(i*3+40), y:fr(i*5+41), sp:.6+fr(i*7+42)*.7, ln:8+fr(i*9+43)*14});
}

// ---- pose program ----
let pose=P.pose;
const base=P.pose;
if(base==='walk'){
  // continuous walk cycle
} else if(base==='lean'){
  const ph=md(bt,32);
  if(P.act==='chase'){
    pose = ph<20 ? 'walk' : ph<26 ? 'look' : 'lean';
  } else if(P.act==='reveal'){
    pose = ph<10 ? 'lean' : ph<18 ? 'look' : ph<24 ? 'walk' : 'lean';
  } else { // stakeout
    pose = ph<22 ? 'lean' : ph<28 ? 'look' : 'lean';
  }
}

// ---- motion ----
const breath=Math.sin(K.t*.45)*.5 + K.swell*.35;
const wob=sn(K.t*.55,20);
let step=0, bob=0, sway=0, lookT=0, leanA=0, shoulder=0, gaitX=0;
const bass=K.pulse*.5*en + A.bass*.7;
if(pose==='walk'){
  const c=md(bt,2)/2;                          // 2-beat stride
  step=Math.sin(c*Math.PI*2);
  bob=Math.abs(Math.cos(c*Math.PI*2))*(6+5*en);
  gaitX=Math.sin(bt*Math.PI*.5)*(10+8*en);     // travels across pool
  shoulder=step*.12;
  leanA=.05+step*.03;
} else if(pose==='look'){
  lookT=Math.sin(bt*Math.PI*.5)*(.5+.3*en);    // scanning head turn
  sway=wob*3 + breath*2;
  bob=breath*2 + bass*3;
  shoulder=Math.sin(bt*Math.PI*.5)*.05;
} else { // lean (against wall / smoking)
  leanA=.14+breath*.02;
  sway=Math.sin(bt*Math.PI*.5)*3.4*en + wob*2.4 + bass*2.6;
  bob=breath*3 + bass*3 + Math.abs(Math.sin(bt*Math.PI*.5))*3.4*en;
  shoulder=breath*.03 + bass*.02;
}

// cigarette ember + drag cycle (glows on a slow phrase)
const drag = clp(Math.sin(md(bt,8)/8*Math.PI*2)*.5+.5,0,1);
const ember = .35 + drag*.5 + A.treble*.3;

// ================= DRAW =================
push();
translate(P.x*width, (P.y)*height);        // feet anchor
scale(sc);

// --- light cone from above (layered, cheap) ---
(function(){
  const beamH=250, topW=18, botW=118;
  noStroke();
  for(let g=4;g>=0;g--){
    fill(neon?192:46, neon?24:13, 100, (neon?9:7)-g);
    beginShape();
    vertex(-(topW+g*3)*.5, -beamH);
    vertex((topW+g*3)*.5, -beamH);
    vertex((botW+g*10)*.5, 6);
    vertex(-(botW+g*10)*.5, 6);
    endShape(CLOSE);
  }
  // floor pool of light
  for(let r=0;r<4;r++){ fill(neon?192:44,18,100, 9-r*2); ellipse(0, 4, botW+r*40, 30+r*10); }
})();

// --- rain streaks (in the beam) ---
if(P.density>.02){
  const nR=Math.round(P.density*70);
  stroke(neon?192:44, 12, 100, 26);
  for(let i=0;i<nR;i++){ const R=S.rain[i];
    const yy=frc(R.y + K.t*R.sp*.9)*260-250;
    const xx=(R.x-.5)*150 + wob*4;
    strokeWeight(1);
    line(xx, yy, xx-2, yy+R.ln);
  }
}

// ================= FIGURE =================
// silhouette-first: the detective is a dark mass shaped by the light
function bodyFill(a){
  if(xray){ noFill(); return; }
  if(neon){ fill(H,10,7,a); return; }        // near-black, rim added later
  if(chalk){ fill(210,8,20,a); return; }
  fill(230,30,5,a);                           // deep noir black-blue
}
function rim(a,w){
  // edge light catching the form
  if(xray){ stroke(190,50,96,a); strokeWeight(w); noFill(); return; }
  if(neon){ stroke(H,80,100,a); strokeWeight(w); noFill(); return; }
  if(chalk){ stroke(210,10,96,a); strokeWeight(w); noFill(); return; }
  stroke(44,20,98,a*.9); strokeWeight(w); noFill();
}

push();
translate(sway+gaitX, -bob);
rotate(leanA*.5);

const legSpread=pose==='walk'?step*16:6;
const hipY=-96, shY=-186;

// ---- legs (trousers) ----
(function(){
  const sw=13;
  // back leg
  push();
  bodyFill(100); if(xray){ rim(80,2);}
  // left/back
  rimLeg(-legSpread*.5, pose==='walk'? step*.4:.06, sw);
  rimLeg(legSpread*.5, pose==='walk'? -step*.4:-.06, sw);
  pop();
})();
function rimLeg(dx,ang,sw){
  push(); translate(dx, hipY); rotate(ang);
  if(!xray){ bodyFill(100); noStroke();
    beginShape(); vertex(-sw*.5,0); vertex(sw*.5,0); vertex(sw*.42,86); vertex(-sw*.5,86); endShape(CLOSE);
    // shoe
    bodyFill(100); ellipse(2,92,sw*1.7,10);
  } else { rim(85,2); line(0,0,ang*10,88); }
  // rim light on outer edge
  rim(neon?90:60,1.6); line(-sw*.5,4,-sw*.5,84);
  pop();
}

// ---- long coat / trench (the signature mass) ----
(function(){
  const flare=P.throw*18;
  const coatW=52;
  if(!xray){ bodyFill(100); noStroke(); }
  else { rim(88,2); }
  beginShape();
  vertex(-coatW*.5, shY+8);                         // left shoulder
  bezierVertex(-coatW*.7,-150,-coatW*.75,-70, -coatW*.6-flare*(.6+.6*Math.abs(step)), -6);
  vertex(coatW*.6+flare*(.6+.6*Math.abs(step)), -6); // hem swings with stride
  bezierVertex(coatW*.75,-70, coatW*.7,-150, coatW*.5, shY+8);
  bezierVertex(coatW*.3, shY-4, -coatW*.3, shY-4, -coatW*.5, shY+8);
  endShape(CLOSE);
  // coat front seam + lapels (form-from-shadow, not outline)
  if(!xray){
    rim(neon?70:46,1.6);
    line(0,shY+6,0,-10);                              // center seam catches light
    // lapel triangles
    noStroke();
    if(neon){ fill(H,70,90,50);} else if(chalk){ fill(210,10,92,55);} else { fill(44,18,96,42);}
    beginShape(); vertex(-3,shY+4); vertex(-16,shY-2); vertex(-6,-40); endShape(CLOSE);
    beginShape(); vertex(3,shY+4); vertex(16,shY-2); vertex(6,-40); endShape(CLOSE);
    // belt
    if(neon){ stroke(H,80,100,70);} else if(chalk){ stroke(210,12,96,70);} else stroke(44,22,98,60);
    strokeWeight(3); line(-coatW*.42,-70, coatW*.42,-70);
  } else {
    // x-ray: ribs/spine schematic
    rim(70,1.2);
    line(0,shY+6,0,-12);
    for(let i=0;i<5;i++){ const yy=shY+30+i*22; line(-16,yy,16,yy); }
  }
})();

// ---- arms ----
(function(){
  const armDrop=pose==='look'? lookT*6 : 0;
  // near arm (holding cigarette up when lean, or swinging when walk)
  let hxr, hyr;
  if(pose==='walk'){ hxr=18+step*10; hyr=-96; }
  else { hxr=16; hyr=-150; } // hand near face for cigarette
  if(!xray){
    if(neon){ stroke(H,12,10);} else if(chalk){ stroke(210,8,22);} else stroke(230,30,6);
    strokeWeight(15); noFill(); }
  else { rim(85,2); }
  // far arm (down, behind coat) - subtle
  strokeCap && strokeCap(ROUND);
  line(-16,shY+14, -20+shoulder*20, -104);
  // near arm to hand
  const ex=(16+hxr)*.5+6, ey=(shY+14+hyr)*.5+shoulder*10;
  beginShape(); vertex(16,shY+14); if(typeof quadraticVertex==='function'){ quadraticVertex(ex,ey,hxr,hyr);} else { vertex(ex,ey); vertex(hxr,hyr);} endShape();
  // rim on near arm
  rim(neon?80:52,1.6); line(20,shY+18,hxr+2,hyr);
  // hand
  if(!xray){ if(neon){ fill(28,20,20);} else if(chalk){ fill(210,8,30);} else fill(24,26,16);} noStroke();
  if(!xray) ellipse(hxr,hyr,10,10);
  S.hx=hxr; S.hy=hyr;
})();

// ---- head + fedora ----
push();
translate(lookT*10, shY-4);
rotate(lookT*.5 + wob*.02);
// head
if(!xray){ if(neon){ fill(28,18,18);} else if(chalk){ fill(210,8,32);} else fill(24,25,15);} noStroke();
if(!xray){
  beginShape();
  vertex(-9,2); bezierVertex(-11,-10,-8,-20,0,-20); bezierVertex(8,-20,11,-10,9,2);
  bezierVertex(8,10,-8,10,-9,2); endShape(CLOSE);
} else { rim(85,2); ellipse(0,-8,20,26); }
// jaw/cheek rim light (chiaroscuro — the face is half-lit)
rim(neon?85:58,1.8);
noFill(); beginShape(); vertex(9,2); bezierVertex(8,10,2,12,-2,11); endShape();
// hat brim (wide fedora shadow)
if(!xray){ if(neon){ fill(H,10,8);} else if(chalk){ fill(210,8,18);} else fill(230,30,4);} noStroke();
if(!xray){
  ellipse(0,-14, 46, 12);                     // brim
  // crown
  beginShape(); vertex(-13,-15); bezierVertex(-12,-30,12,-30,13,-15); endShape(CLOSE);
  // hatband
  if(neon){ fill(H,70,80,70);} else if(chalk){ fill(210,10,88,60);} else fill(44,16,90,42);
  rect(-13,-17,26,3);
} else {
  rim(70,1.4); ellipse(0,-14,46,12); line(-12,-15,-12,-28); line(12,-15,12,-28);
}
// brim front dips over eyes — a hard shadow slash
if(!xray){ if(neon){ fill(H,10,6,90);} else if(chalk){ fill(210,8,14,88);} else fill(230,30,3,92);} noStroke();
if(!xray) quad(-16,-13, 16,-13, 12,-6, -12,-6);
pop(); // head

pop(); // figure translate

// ---- cigarette smoke ribbon (rises from hand) ----
(function(){
  if(xray) return;
  const baseX=(S.hx!=null?S.hx:16)+sway+gaitX, baseY=(S.hy!=null?S.hy:-150)-bob-4;
  // ember
  noStroke();
  fill(14,90,100, 70+ember*30); ellipse(baseX+4, baseY, 3+ember*2,3+ember*2);
  fill(20,60,100, 30); ellipse(baseX+4, baseY, 7,7);
  // smoke
  noFill();
  for(let i=0;i<S.smoke.length;i++){ const M=S.smoke[i];
    const life=M.sp;
    if(neon) stroke(H,30,100, 14); else stroke(0,0,100, 12+drag*8);
    strokeWeight(M.w*.5);
    beginShape();
    for(let s=0;s<=6;s++){
      const yy=baseY - s*16 - frc(K.t*.15*life+M.ph)*10;
      const amp=(s*s)*.5*(1+drag*.6);
      const xx=baseX+4 + Math.sin(K.t*.6*M.sp + M.ph + s*.6)*amp*.14 + M.drift*s*1.4;
      if(s===0) vertex(xx,yy); else curveVertex(xx,yy);
    }
    endShape();
  }
})();

pop(); // root

// --- film grain (full-frame, seed-fixed jitter) ---
(function(){
  const gj=Math.floor(K.t*12);
  noStroke();
  for(let i=0;i<S.grain.length;i++){ const G=S.grain[i];
    const a=fr(i*2+gj)*(chalk?10:15);
    fill(0,0, fr(i)>.5?100:0, a);
    const gx2=frc(G.x+.5+ i*0.013)*width + sn(K.t*3+i,i)*3;
    const gy2=frc(G.y+.5+ i*0.017)*height;
    ellipse(gx2, gy2, G.r*u*.006+.6, G.r*u*.006+.6);
  }
})();
